-- ADERVIS Intelligence · ответы второй анкеты владельцев (19.10.2026)
--
-- «История и люди»: как появилась студия, кто за что отвечает, как устроена
-- работа с клиентом, что студия обещает, кейсы и планы. Всё — со слов
-- владельцев («Со слов команды»); публичное — то, что можно говорить
-- клиентам и в контенте, внутреннее — для себя.

insert into public.knowledge (id, title, body, category, source, access, status) values
('k-own-history', 'История ADERVIS', $b$Артём Никитин и Александр Хатуов работали вместе в другой компании и с 2017 года делали видео и графику для «Битвы роботов». В 2019 году открыли свою студию — ADERVIS — и продолжили работать с «Битвой роботов» уже от своего имени.

Студия росла: было своё помещение и команда из 11 человек. Пандемия заставила перестроиться — сейчас проекты ведут сами руководители, а на крупные задачи собирается команда из постоянных фрилансеров: оператор, фотограф, монтажёр.

Первые заказы — дизайн и оформление соцсетей, моушн-анимация, сайты; все ранние кейсы по порядку — на Behance: https://www.behance.net/adervisdigital. Поворотными стали крупные клиенты с комплексом услуг (Express Import, «Бани онлайн»), покупка своего оборудования, своё помещение и переход на ИИ-инструменты.$b$, 'Компания', 'Анкета владельцев 2, 19.10.2026', 'Публичное', 'Со слов команды'),

('k-own-history-hard', 'Трудный период и как вышли', $b$Самый тяжёлый период — пандемия и карантин. Студия отказалась от офиса и сократила штат с 11 человек до двух руководителей, которые стали делать всё сами, развивать навыки и вкладываться в оборудование. Сейчас на большие проекты привлекают фрилансеров.

Для публичных текстов: говорить о том, что руководители ведут проекты сами и умеют всё — от съёмки до 3D, без подробностей о сокращениях.$b$, 'Компания', 'Анкета владельцев 2, 19.10.2026', 'Внутреннее', 'Со слов команды'),

('k-own-name', 'Откуда название ADERVIS', $b$Название и логотип придумал Артём ещё студентом. Позже у слова появилось много смыслов: оно созвучно английскому advertising — «реклама», а знак легко показать пальцами рук.

Идея слогана из прошлого: «Идеи обретают форму» — не утверждён.$b$, 'Бренд', 'Анкета владельцев 2, 19.10.2026', 'Публичное', 'Со слов команды'),

('k-own-people', 'Артём и Александр — кто за что отвечает', $b$Артём Никитин — моушн-графика, дизайн, анимация, VFX и 3D, сайты, программирование. Гордится ADERVIS в целом.
Александр Хатуов — съёмка, монтаж, фото, постановка, сценарии, маркетинг и продвижение.

Переговоры: кто нашёл клиента, тот и ведёт; видео — Александр, дизайн и ИИ — Артём; на встречи часто ходят вдвоём. В соцсетях лицо студии — оба, в кадре. Личное — только в личных аккаунтах, в ADERVIS — только работа: закулисье съёмок, работа с техникой и светом, как делаются ИИ-ролики.$b$, 'Авторы', 'Анкета владельцев 2, 19.10.2026', 'Публичное', 'Со слов команды'),

('k-own-process', 'Как мы работаем: этапы и условия', $b$Этапы проекта: бриф или созвон → смета и КП из CRM → договор → предоплата → сценарий или раскадровка → съёмка → монтаж и графика → правки → сдача и закрывающие документы.

Предоплата — 50%, постоянным клиентам — без предоплаты. В цену входят два–три круга правок. Рекламный ролик — обычно 1–4 недели от брифа до сдачи. За месяц студия берёт 3–5 проектов — зависит от их размера.

Оформление: руководители работают как самозанятые — договор, чек «Мой налог», цены без НДС.$b$, 'Услуги', 'Анкета владельцев 2, 19.10.2026', 'Публичное', 'Со слов команды'),

('k-own-selfemployed', 'Самозанятость: что учитывать в сделках', $b$Руководители работают как самозанятые: договор, чек «Мой налог», цены без НДС. Лимит дохода самозанятого — 2,4 млн ₽ в год на человека — крупный проект лучше делить между двумя руководителями. Крупные заказчики и тендеры могут требовать ИП или ООО и НДС — уточнять до отправки КП.$b$, 'Компания', 'Анкета владельцев 2, 19.10.2026', 'Внутреннее', 'Со слов команды'),

('k-own-promises', 'Что мы обещаем клиенту', $b$Всегда:
— сроки фиксируем в договоре;
— руководитель на связи весь проект;
— смета без скрытых платежей;
— не попали в задачу — переделаем.

Чего не делаем: не срываем сроки, не отдаём проекты стажёрам, не пропадаем после оплаты.

Хотим быть для клиента подрядчиком, который делает быстро и качественно, партнёром, который думает о результате бизнеса, и экспертом, к которому идут за идеей. Делаем любые стили — от кино и документального до яркой рекламы и технологичной 3D- и ИИ-графики.$b$, 'Компания', 'Анкета владельцев 2, 19.10.2026', 'Публичное', 'Со слов команды'),

('k-own-equipment', 'Своё оборудование', $b$Своё: камеры, дрон, свет, стабилизатор, звук — петлички и рекордер. Студия постоянно вкладывается в оборудование: на деньги от «Битвы роботов» купили технику и продолжают на ней работать. В планах на год — новые компьютеры и ноутбуки.$b$, 'Компания', 'Анкета владельцев 2, 19.10.2026', 'Публичное', 'Со слов команды'),

('k-case-battle-robots', 'Кейс: «Битва роботов» с 2017 года', $b$Работаем с проектом с самого начала: с 2017 года — в составе другой компании, с 2019 года — как ADERVIS. «Битва роботов» стала международным проектом: суперфинал на Играх будущего в Казани в 2024 году — 16 команд из 11 стран, призовой фонд $500 000. Делаем видеосъёмку и графику.

Кейс на сайте: https://adervis.ru/cases/battle-of-robots/$b$, 'Кейсы', 'https://adervis.ru/cases/battle-of-robots/', 'Публичное', 'Со слов команды'),

('k-case-shabani', 'Кейс: SHABANI ENERGY — реклама с 3D-банкой', $b$Рекламный ролик энергетика SHABANI ENERGY со вкусом «Яблоко-Киви»: сняли реальную банку на камеру, собрали её в 3D с этикеткой вкуса и смонтировали динамичный ролик.

Кейс на сайте: https://adervis.ru/cases/shabani-energy/$b$, 'Кейсы', 'https://adervis.ru/cases/shabani-energy/', 'Публичное', 'Со слов команды'),

('k-case-lukoil-ai', 'Кейс: ИИ-интро для корпоративной игры «Лукойла»', $b$ИИ-анимация интро для корпоративной игры об охране труда «Время супергероев» компании «Лукойл». Готовый ролик — за 7 дней. Владельцы разрешили рассказывать об этой работе; кейс опубликован на сайте.

Кейс на сайте: https://adervis.ru/cases/lukoil-ai/$b$, 'Кейсы', 'https://adervis.ru/cases/lukoil-ai/', 'Публичное', 'Публичный источник'),

('k-own-3y', 'Куда идём: три года', $b$Через три года владельцы видят: студию с командой 5–10 человек, продукты (CRM и Stock), которые приносят больше студии, свою студию-павильон в Перми и работу на Москву и другие города. Готовы нанимать людей в штат. Интересны тендеры и госзаказ — пока не участвовали.

Ниши, которые в Перми охотнее платят за визуал: производство, медицина и клиники, мероприятия, госзаказ и тендеры.$b$, 'Стратегия', 'Анкета владельцев 2, 19.10.2026', 'Внутреннее', 'Со слов команды'),

('k-own-products-status', 'Статус продуктов на октябрь 2026', $b$ADERVIS CRM официально ещё не запущена. ADERVIS Stock запущен около двух месяцев назад. Продукты делали потому, что сами нуждались в таком инструменте и хотели доход, не зависящий от заказов.$b$, 'Продукты', 'Анкета владельцев 2, 19.10.2026', 'Внутреннее', 'Со слов команды'),

('k-own-instagram', 'Instagram: витрина и переписка', $b$Instagram ведём как витрину работ и используем для переписки с клиентами. Директ можно подключить к «Диалогам» — нужен бизнес-аккаунт, связанный со страницей Facebook.$b$, 'Каналы', 'Анкета владельцев 2, 19.10.2026', 'Внутреннее', 'Со слов команды')
on conflict (id) do nothing;

-- решения: бюджет рекламы — пополам между студией и CRM
update public.decisions
   set title = 'Реклама: до 10 000 ₽ в месяц — пополам студия и CRM, начинаем с ВКонтакте',
       why = why || E'\n\nАнкета 2 (19.10.2026): бюджет делим пополам между студией и CRM.'
 where id = 'd-ads-budget-2026-10' and why not like '%пополам%';

update public.decisions
   set status = 'Отменено',
       outcome = 'Владельцы решили делить рекламный бюджет пополам между студией и CRM (анкета 2, 19.10.2026) — реклама CRM идёт уже сейчас.'
 where id = 'd-crm-ads' and status <> 'Отменено';
